import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const p=JSON.parse('{"title":"Agentic Video Generation","description":"","frontmatter":{"title":"Agentic Video Generation","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/agentic.md","filePath":"en/tutorials/agentic.md","lastUpdated":null}'),o={name:"en/tutorials/agentic.md"};function r(l,e,s,h,c,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="agentic-video-generation" tabindex="-1">Agentic Video Generation <a class="header-anchor" href="#agentic-video-generation" aria-label="Permalink to &quot;Agentic Video Generation&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/agentic">智能体视频生成</a><strong>Coverage</strong>: June 2025 – July 2026, tracing foundational work back to 2023. <strong>Papers</strong>: <a href="/notes/en/papers/#tut-agentic">29 deep-read notes</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it gives the complete chapter-by-chapter structure and states what each chapter argues. Every derivation, table, diagram and per-paper breakdown lives in the <a href="/notes/tutorials/agentic">Chinese edition</a>; the <a href="/notes/en/papers/">paper library</a> is fully browsable in English.</p></div><h2 id="what-this-tutorial-is-about" tabindex="-1">What this tutorial is about <a class="header-anchor" href="#what-this-tutorial-is-about" aria-label="Permalink to &quot;What this tutorial is about&quot;">​</a></h2><p>The shift the tutorial describes is from &quot;an artist producing a finished drawing in one pass&quot; to &quot;a film crew working together&quot;. A single forward pass through a video model cannot hold a multi-shot story consistent, cannot check its own output, and cannot revise. Agentic video generation replaces that single pass with a loop: <strong>plan · generate · evaluate · revise</strong>.</p><p>Two technical families are separated throughout. Family A is <strong>orchestration</strong> — an external agent (or several) decomposes the task, calls generators and tools, keeps state, and verifies results. Family B is <strong>reasoning-native generation</strong>, where the reasoning is internal to the model. The tutorial also defines a five-level ladder of &quot;how agentic&quot; a system is, from prompt rewriting up to L5 reasoning-native generation, and uses it to place every system it discusses.</p><h2 id="chapter-outline" tabindex="-1">Chapter outline <a class="header-anchor" href="#chapter-outline" aria-label="Permalink to &quot;Chapter outline&quot;">​</a></h2><h3 id="chapter-0-—-how-to-use-this-tutorial" tabindex="-1">Chapter 0 — How to use this tutorial <a class="header-anchor" href="#chapter-0-—-how-to-use-this-tutorial" aria-label="Permalink to &quot;Chapter 0 — How to use this tutorial&quot;">​</a></h3><ul><li>0.1 What we are covering</li><li>0.2 Suggested reading paths</li><li>0.3 Scope</li><li>0.4 The overall logic</li></ul><h3 id="chapter-1-—-concepts-and-intuition" tabindex="-1">Chapter 1 — Concepts and intuition <a class="header-anchor" href="#chapter-1-—-concepts-and-intuition" aria-label="Permalink to &quot;Chapter 1 — Concepts and intuition&quot;">​</a></h3><ul><li>1.1 From &quot;one-pass artist&quot; to &quot;collaborating film crew&quot;</li><li>1.2 Why a single forward generation is not enough</li><li>1.3 The agentic spectrum: five levels from weak to strong</li><li>1.4 The two technical families</li><li>1.5 Relation to world models and post-training (three maps, one puzzle)</li><li>1.6 A minimal mental model</li></ul><h3 id="chapter-2-—-mathematical-principles-and-key-techniques" tabindex="-1">Chapter 2 — Mathematical principles and key techniques <a class="header-anchor" href="#chapter-2-—-mathematical-principles-and-key-techniques" aria-label="Permalink to &quot;Chapter 2 — Mathematical principles and key techniques&quot;">​</a></h3><p>Formalises generation as sequential decision-making, then works through the six mechanisms that make the loop work.</p><ul><li>2.1 Formalisation: turning generation into decision-making</li><li>2.2 Technique 1: hierarchical planning</li><li>2.3 Technique 2: memory and state tracking</li><li>2.4 Technique 3: tool use and structured grounding</li><li>2.5 Technique 4: reflection and closed-loop verification</li><li>2.6 Technique 5: multi-agent collaboration</li><li>2.7 Technique 6: reasoning-native generation (L5)</li><li>2.8 Agentic RL: training the orchestration/reasoning policy itself</li><li>2.9 Chapter summary</li></ul><h3 id="chapter-3-—-task-taxonomy" tabindex="-1">Chapter 3 — Task taxonomy <a class="header-anchor" href="#chapter-3-—-task-taxonomy" aria-label="Permalink to &quot;Chapter 3 — Task taxonomy&quot;">​</a></h3><ul><li>3.0 Panorama of tasks</li><li>3.1 Long narrative / story video generation</li><li>3.2 Novel-to-film generation</li><li>3.3 Short drama / short-form video generation</li><li>3.4 Multi-shot consistent video</li><li>3.5 Joint audio-visual narrative generation</li><li>3.6 Data / knowledge to explainer video</li><li>3.7 Directorial and controllable generation</li><li>3.8 Reasoning-native video generation</li><li>3.9 Physically plausible generation</li><li>3.10 3D/4D scene generation</li><li>3.11 Mapping tasks back onto the mental model</li></ul><h3 id="chapter-4-—-benchmarks-and-evaluation" tabindex="-1">Chapter 4 — Benchmarks and evaluation <a class="header-anchor" href="#chapter-4-—-benchmarks-and-evaluation" aria-label="Permalink to &quot;Chapter 4 — Benchmarks and evaluation&quot;">​</a></h3><p>Argues that agentic video is unusually hard to score, because quality now depends on narrative coherence and instruction compliance across shots rather than per-clip fidelity.</p><ul><li>4.1 Why evaluating agentic video is especially hard</li><li>4.2 Representative benchmarks</li><li>4.3 Decomposing the evaluation dimensions (five questions to remember)</li><li>4.4 VLM-as-judge: the shared substrate of evaluation and training</li><li>4.5 Three practical recommendations for using benchmarks</li></ul><h3 id="chapter-5-—-data" tabindex="-1">Chapter 5 — Data <a class="header-anchor" href="#chapter-5-—-data" aria-label="Permalink to &quot;Chapter 5 — Data&quot;">​</a></h3><ul><li>5.1 What data is needed: from video–text pairs to &quot;creative blueprints&quot;</li><li>5.2 Representative datasets</li><li>5.3 How the data gets made: agentic annotation and self-generation</li><li>5.4 Two principles for data</li></ul><h3 id="chapter-6-—-methods-and-representative-systems-core-chapter" tabindex="-1">Chapter 6 — Methods and representative systems (core chapter) <a class="header-anchor" href="#chapter-6-—-methods-and-representative-systems-core-chapter" aria-label="Permalink to &quot;Chapter 6 — Methods and representative systems (core chapter)&quot;">​</a></h3><ul><li>6.1 Multi-agent orchestration</li><li>6.2 Stateful world modelling for narrative</li><li>6.3 Memory-driven consistency</li><li>6.4 Geometry and structure grounding</li><li>6.5 Reflective closed loops and tool verification</li><li>6.6 Reasoning-native generation (Family B / L5)</li><li>6.7 Agentic RL training (cutting across both families)</li><li>6.8 Master table of method families</li><li>6.9 Composition recipes: assembling families into a system</li><li>6.10 Further representative systems worth dissecting, by theme</li></ul><h3 id="chapter-7-—-core-challenges-and-research-trends" tabindex="-1">Chapter 7 — Core challenges and research trends <a class="header-anchor" href="#chapter-7-—-core-challenges-and-research-trends" aria-label="Permalink to &quot;Chapter 7 — Core challenges and research trends&quot;">​</a></h3><ul><li>7.1 Six core challenges</li><li>7.2 Five research trends</li><li>7.3 A possible endgame: the thinking &quot;AI film crew&quot; collapsing into one unified model</li></ul><h3 id="chapter-8-—-paper-and-resource-list-2025-06–2026-07" tabindex="-1">Chapter 8 — Paper and resource list (2025.06–2026.07) <a class="header-anchor" href="#chapter-8-—-paper-and-resource-list-2025-06–2026-07" aria-label="Permalink to &quot;Chapter 8 — Paper and resource list (2025.06–2026.07)&quot;">​</a></h3><p>Grouped into: naming/survey/framework work; narrative, film and long-video generation; multimodal, audio-visual and data video; directorial control and geometric grounding; physics, closed-loop verification and executable generation; reasoning-native generation (L5); benchmarks and data; foundational work from 2023 to mid-2025; and adjacent directions cross-referenced to the sister tutorials.</p><h2 id="related-tutorials" tabindex="-1">Related tutorials <a class="header-anchor" href="#related-tutorials" aria-label="Permalink to &quot;Related tutorials&quot;">​</a></h2><ul><li><a href="/notes/en/tutorials/world-models">World Models</a> — the interactive simulator side of the same problem</li><li><a href="/notes/en/tutorials/acceleration-distillation">Acceleration &amp; Distillation</a> — making each generation call cheap enough that a loop is affordable</li><li><a href="/notes/en/tutorials/post-training-rl">Post-Training &amp; Reinforcement Learning</a> — aligning the generator the agent is calling</li></ul>',29)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
